<?php
namespace App\Http\Controllers\AI;
use App\Http\Controllers\Controller; use App\Http\Requests\AI\StoreNotebookDocumentsRequest; use App\Models\NotebookDocument; use App\Services\AI\NotebookService; use Illuminate\Http\Request;
class NotebookDocumentController extends Controller { public function __construct(private NotebookService $notebook){} public function index(Request $r){$data=$r->validate(['conversation_id'=>['required','uuid']]);return response()->json(['status'=>'success','data'=>$this->notebook->list($r->user(),$data['conversation_id'])]);} public function store(StoreNotebookDocumentsRequest $r){$data=$r->validated();$items=[];foreach($r->file('documents') as $file)$items[]=$this->notebook->data($this->notebook->ingest($r->user(),$data['conversation_id'],$file));return response()->json(['status'=>'success','data'=>$items],201);} public function show(Request $r,NotebookDocument $document){abort_unless($document->user_id===$r->user()->id,404);return response()->json(['status'=>'success','data'=>$this->notebook->data($document)]);} public function destroy(Request $r,NotebookDocument $document){$this->notebook->delete($r->user(),$document);return response()->json(['status'=>'success','data'=>null]);} public function query(Request $r){$data=$r->validate(['conversation_id'=>['required','uuid'],'question'=>['required','string','min:3','max:500'],'document_ids'=>['nullable','array','max:50'],'document_ids.*'=>['uuid']]);return response()->json(['status'=>'success','data'=>$this->notebook->query($r->user(),$data['conversation_id'],$data['question'],$data['document_ids']??[])]);} }
